// src/pages/ChatApp.jsx
import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const ChatApp = () => {
  const [messages, setMessages] = useState([]);
  const [chatHistory, setChatHistory] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  // Read user details from localStorage
  const userId = localStorage.getItem("user_id");
  const userEmail = localStorage.getItem("user_email");

  useEffect(() => {
    if (!userId) {
      navigate("/"); // Redirect if not logged in
      return;
    }

    const fetchChatHistory = async () => {
      try {
        const response = await axios.get(`http://127.0.0.1:8000/chat_history/${userId}`);
        setChatHistory(response.data.history || []);
      } catch (error) {
        console.error("Error fetching chat history:", error);
      }
    };

    fetchChatHistory();
  }, [userId, navigate]);

  const handleSendMessage = async () => {
    if (newMessage.trim()) {
      setLoading(true);
      const userMessage = { id: Date.now(), message: newMessage, sender: "user" };
      setMessages((prev) => [...prev, userMessage]);

      try {
        const response = await axios.post("http://127.0.0.1:8000/chat", {
          user_id: userId,
          user_email: userEmail,
          message: newMessage,
          chat_id: "default_chat", // You can update this if you add support for multiple chats
        });

        const botReply = response.data.bot || "Hmm, I didn’t get that. Try again!";
        const botMessage = { id: Date.now() + 1, message: botReply, sender: "bot" };
        setMessages((prev) => [...prev, botMessage]);
      } catch (error) {
        console.error("Error sending message:", error);
      }

      setNewMessage("");
      setLoading(false);
    }
  };

  return (
    <div className="chat-container">
      <div className="sidebar">
        <h3>Chat History</h3>
        <ul>
          {chatHistory.map((chat) => (
            <li key={chat.id}>{chat.message}</li>
          ))}
        </ul>
      </div>
      <div className="chat-area">
        <div className="chat-messages">
          {messages.map((msg) => (
            <div key={msg.id} className={msg.sender === "user" ? "user-message" : "bot-message"}>
              {msg.message}
            </div>
          ))}
        </div>
        <div className="chat-input">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            disabled={loading}
          />
          <button onClick={handleSendMessage} disabled={loading}>
            Send
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatApp;
